Definition read_size_val (F : fbv) : Z := Z.min (Z.max 512 (fb_cap F - fb_size F)) 65536.
Lemma read_size_val_range : forall F, 512 <= read_size_val F <= 65536.
Proof. intros F. unfold read_size_val. lia. Qed.
Definition fb_consume (F : fbv) (k : Z) : fbv :=
  if k <? fb_size F then mkFB (fb_begin F) (fb_in F + k) (fb_out F) (fb_last F) (fb_end F)
  else mkFB (fb_begin F) (fb_begin F) (fb_begin F) (fb_last F) (fb_end F).
Definition fb_prep_inplace (F : fbv) (n : Z) : bool := n <=? fb_end F - fb_out F.
Definition fb_prep_slide (F : fbv) (n : Z) : bool := n <=? fb_cap F - fb_size F.
Definition fb_newsize (F : fbv) (n : Z) : Z := Z.max (2 * fb_size F) (fb_size F + n).
Definition fb_prep_small (FB : fbv) (n : Z) : fbv :=
  if fb_prep_inplace FB n
  then mkFB (fb_begin FB) (fb_in FB) (fb_out FB) (fb_out FB + n) (fb_end FB)
  else mkFB (fb_begin FB) (fb_begin FB) (fb_begin FB + fb_size FB) (fb_begin FB + fb_size FB + n) (fb_end FB).
Definition fb_prep_grow (FB : fbv) (n A' : Z) : fbv :=
  mkFB A' A' (A' + fb_size FB) (A' + fb_size FB + n) (A' + fb_newsize FB n).
Definition fb_X (fb : Z) (FB : fbv) : list (Z * Z) := [(fb, fb + SZ_FB); (fb_begin FB, fb_end FB)].

(* [comment removed for export] *)
Definition st_closed (S : statev) : statev := mkST (st_hdr S) 0 (st_fb S) STREAM_EOF (st_nread S) (st_nread_bytes S).
Definition impl_one (w i vb this vcap : Z) : implv := mkIMPL (mkSPC AVP_SPCI_IMPL 1 w i) 0 vb [this] vcap.
Definition impl_none (w i vb vcap : Z) : implv := mkIMPL (mkSPC AVP_SPCI_IMPL 1 w i) 0 vb [] vcap.
Definition fb_off (Fb : fbv) (a n : Z) : Prop := fb_end Fb <= a \/ a + n <= fb_begin Fb.
Definition impl_weak (I : implv) (w : Z) : implv :=
  mkIMPL (mkSPC (spc_vptr (im_hdr I)) (spc_use (im_hdr I)) w (spc_init (im_hdr I))) (im_lk I) (im_vb I) (im_states I) (im_vcap I).

(* [comment removed for export] *)
Definition rs_take (ds : list byte) (tn : Z) : Z := Z.min (zlength ds) tn.
Definition rs_state (S : statev) (ds : list byte) (tn : Z) : statev :=
  mkST (st_hdr S) 0
       (if zlength ds =? 0 then st_fb S else fb_consume (st_fb S) (rs_take ds tn))
       (st_code S) (st_nread S + 1) (st_nread_bytes S + rs_take ds tn).

