(* [comment removed for export] *)
Definition AImplBlockC (LB : list block) (m : mem) (b : Z) (I : implv) : Prop :=
  exists p j7, In (p, b, SZ_SPCI_IMPL) LB /\ rblock_range b SZ_SPCI_IMPL
  /\ rw_cells asegs m b (SpcHdrCells (im_hdr I) j7) /\ spc_ok (im_hdr I) /\ spc_vptr (im_hdr I) = AVP_SPCI_IMPL
  /\ APMutex m (b + O_SPC_STORAGE + O_IMPL_MUTEX) (im_lk I)
  /\ rw_cells asegs m (b + O_SPC_STORAGE + O_IMPL_VEC_BEGIN)
       [C8 (wz (im_vb I)); C8 (wz (im_vb I + 8 * zlength (im_states I))); C8 (wz (im_vb I + 8 * im_vcap I))]
  /\ zlength (im_states I) <= im_vcap I
  /\ ((im_vcap I = 0 /\ im_vb I = 0)
      \/ (exists q junk, In (q, im_vb I, 8 * im_vcap I) LB /\ rblock_range (im_vb I) (8 * im_vcap I) /\ 0 < im_vcap I
           /\ rw_cells asegs m (im_vb I) [CB (8 * length (im_states I)) (flat_map le8z (im_states I));
                                         CB (Z.to_nat (8 * (im_vcap I - zlength (im_states I)))) junk]
           /\ SHAD m (im_vb I) (cc_shadow (8 * im_vcap I) (8 * zlength (im_states I)))))        (* [comment removed for export] *)
  /\ addressable m b SZ_SPCI_IMPL.

Lemma cc_shadow_full : forall n, 0 <= n -> n mod 8 = 0 -> cc_shadow n n = shadow_of n.
Proof.
  intros n Hn H8. unfold cc_shadow. rewrite Z.sub_diag. change (Z.to_nat (0 / 8)) with 0%nat. cbn [poison_bytes repeat].
  rewrite app_nil_r. rewrite shadow_of_mult8 by assumption. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma AImplBlock_C : forall LB m b I,
  AImplBlock LB m b I -> (im_vcap I = 0 \/ zlength (im_states I) = im_vcap I) -> AImplBlockC LB m b I.
Proof.
  intros LB m b I (p & j7 & IN & RB & CH & OK & EV & PM & CV & LE & ST & AD) FULL. exists p, j7.
  repeat (split; [assumption|]). split; [| exact AD].
  destruct ST as [Z0|(q & junk & INq & RBq & POS & CS & ADq)]; [left; exact Z0| right]. exists q, junk.
  split; [exact INq|]. split; [exact RBq|]. split; [exact POS|]. split; [exact CS|].
  destruct FULL as [Z0|E]; [lia|]. rewrite E. rewrite cc_shadow_full; [exact (proj2 ADq)| lia| lia].
Qed.

Lemma AImplBlockC_full : forall LB m b I,
  AImplBlockC LB m b I -> (im_vcap I = 0 \/ zlength (im_states I) = im_vcap I) -> AImplBlock LB m b I.
Proof.
  intros LB m b I (p & j7 & IN & RB & CH & OK & EV & PM & CV & LE & ST & AD) FULL. exists p, j7.
  repeat (split; [assumption|]). split; [| exact AD].
  destruct ST as [Z0|(q & junk & INq & RBq & POS & CS & SH)]; [left; exact Z0| right]. exists q, junk.
  split; [exact INq|]. split; [exact RBq|]. split; [exact POS|]. split; [exact CS|].
  destruct FULL as [Z0|E]; [lia|]. split; [lia|]. rewrite E, cc_shadow_full in SH; [exact SH| lia|].
  destruct RBq as (_ & R2 & _). clear - R2. Z.div_mod_to_equations. lia.
Qed.
