Lemma AImplBlockC_transport : forall W LB m m' b I,
  AImplBlockC LB m b I -> munch W m m' -> wmono asegs m m' -> disjoint_from W b SZ_SPCI_IMPL ->
  (0 < im_vcap I -> disjoint_from W (im_vb I) (8 * im_vcap I)) ->
  disjoint_from W (sh b) (nsh SZ_SPCI_IMPL) ->
