(* [comment removed for export] *)
Definition AREAD_SIZE_STACK : Z := 16.
(* [comment removed for export] *)
Definition AANNOTATE_VEC_STACK : Z := 16 + AINTRIN_STACK.
(* [comment removed for export] *)
Definition AEMPLACE_BACK_STACK : Z := 112 + AOPNEW_STACK.
(* [comment removed for export] *)
Definition ASTATE_REMOVE_STACK : Z := 64 + AINTRIN_STACK.
(* [comment removed for export] *)
Definition ACLOSE_REMOTE_STACK : Z := 112 + AINTRIN_STACK.

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition read_size_post (ra sp gp tp s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (FB : fbv) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (read_size_val FB)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp).

Definition read_size_stmt : Prop :=
  forall (fb lo : Z) (LB : list block) (FB : fbv) (ds : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  AFlatBuf LB m fb FB ds ->
  fb mod 8 = 0 ->
  stk asegs m lo (bv_unsigned sp) -> lo + AREAD_SIZE_STACK <= bv_unsigned sp -> aceil <= lo ->
  (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m fb SZ_FB ->
  evt asegs (read_size_post ra sp gp tp s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc FB lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz fb) (wz 65536) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_READ_SIZE_FB) fc None m (seg_rom asegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition annot_kind_ok (pc : Z) : Prop := pc = P_A_VEC_STATEP_ANNOT_DELETE \/ pc = P_A_VEC_STATEP_ANNOT_SHRINK \/ pc = P_A_VEC_STATEP_ANNOT_NEW.

Definition annotate_vec_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (vb n nm lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (sh vb, sh vb + n)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ SHAD m' vb (cc_shadow (8 * n) (nm - vb))
    /\ ACONST m'.

(* [comment removed for export] *)
Definition annot_old (pc vb ve n k : Z) : Z :=
  if pc =? P_A_VEC_STATEP_ANNOT_DELETE then ve else if pc =? P_A_VEC_STATEP_ANNOT_SHRINK then vb + 8 * k else vb + 8 * n.
Definition annot_new (pc vb ve n k : Z) : Z :=
  if pc =? P_A_VEC_STATEP_ANNOT_DELETE then vb + 8 * n else if pc =? P_A_VEC_STATEP_ANNOT_SHRINK then ve else vb + 8 * k.

Definition annotate_vec_stmt (pc : Z) : Prop :=
  forall (V vb ve n k lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ro_cells asegs m V [C8 (wz vb); C8 (wz ve); C8 (wz (vb + 8 * n))] ->
  0 < vb -> rblock_range vb (8 * n) -> 8 * n <= 2^16 ->
  vb <= annot_old pc vb ve n k <= vb + 8 * n -> vb <= annot_new pc vb ve n k <= vb + 8 * n ->
  (annot_old pc vb ve n k) mod 8 = 0 -> (annot_new pc vb ve n k) mod 8 = 0 -> 0 <= k < 2^60 ->
  SHAD m vb (cc_shadow (8 * n) (annot_old pc vb ve n k - vb)) ->
  stk asegs m lo (bv_unsigned sp) -> lo + AANNOTATE_VEC_STACK <= bv_unsigned sp -> aceil <= lo ->
  (V + 24 <= lo \/ bv_unsigned sp <= V) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m V 24 -> V mod 8 = 0 ->
  evt asegs (annotate_vec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc vb n (annot_new pc vb ve n k) lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz V) (wz k) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m (seg_rom asegs)).

(* [comment removed for export] *)
Section W2.
  Variable H : asr.

Definition emplace_back_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block) (LF : list fframe) (V x lo B shi : Z) (m : mem) (mo : Model) : config -> Prop :=
  fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : as_St H) (p : bptr) (A : Z),
    as_VIS H s' (cfg_ms c) = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
    /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' (errno_addr tp) [C4 errv'] /\ as_rauxv_ok H m' B
    /\ rblock_range A 8 /\ as_RHEAP H s' ((p, A, 8) :: LB) m'
    /\ rw_cells asegs m' V [C8 (wz A); C8 (wz (A + 8)); C8 (wz (A + 8))]
    /\ rw_cells asegs m' A [C8 (wz x)]
    /\ addressable m' A 8
    /\ xpres H LB (bv_unsigned sp) [(V, V + 24)]%Z m m'
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
    /\ as_AL H s' >= as_AL H s - as_Cm H 8.

Definition emplace_back_stmt : Prop :=
  forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (msF : machine_state) (m : mem) (mo : Model)
         (s : as_St H) (LB : list block) (LF : list fframe) (V X x lo B shi : Z) (errv : word),
    as_VIS H s msF = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                        F (Z_to_bv 64 P_A_VEC_STATEP_EMPLACE_BACK) fc None m (seg_rom asegs) ->
    a0 = Z_to_bv 64 V -> a1 = Z_to_bv 64 X ->
    rw_cells asegs m V [C8 (wz 0); C8 (wz 0); C8 (wz 0)] -> aobj LB LF V 24 -> V mod 8 = 0 -> accessible m V 24 ->
    ro_cells asegs m X [C8 (wz x)] -> 0 <= x < 2^64 -> bv_unsigned sp <= X -> X + 8 <= shi -> X mod 8 = 0 ->
    as_RHEAP H s LB m -> as_AKREL H s (mkCfg msF mo) ->
    lb_bytes LB + 8 <= as_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= as_LIVE_CNT_MAX H ->
    as_rauxv_ok H m B -> bv_unsigned sp <= B ->
    stk asegs m lo (bv_unsigned sp) -> aceil <= lo -> lo <= bv_unsigned sp - AEMPLACE_BACK_STACK ->
    rw_cells asegs m (errno_addr tp) [C4 errv] -> mem_inv asegs m -> tp = Z_to_bv 64 ATP ->
    bv_unsigned ra mod 2 = 0 ->
    (* [comment removed for export] *)
    bv_unsigned sp mod 16 = 0 ->
    as_RFS H LF m -> ACONST m -> stack0 m lo shi ->
    as_Cm H 8 <= as_AL H s ->
    as_SR H (emplace_back_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF V x lo B shi m mo)
      (mkCfg msF mo).
End W2.

