Definition rm_W (lo : Z) (sp : word) (implb vb vcap : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (implb + 8, implb + 12); (implb + 32, implb + 72); (implb + 80, implb + 88); (vb, vb + 8);
   (sh vb, sh vb + vcap)]%Z.

Definition state_remove_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (implb vb w i vcap lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (rm_W lo sp implb vb vcap) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ AImplBlockC LB m' implb (impl_none w i vb vcap)
    /\ ACONST m' /\ stack0 m' lo shi.

Definition state_remove_stmt : Prop :=
  forall (stb implb vb w i vcap lo shi : Z) (LB : list block)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  ro_cells asegs m (stb + 88) [C8 (wz (implb + 32)); C8 (wz implb)] -> stb mod 16 = 0 -> aapp stb SZ_SPCI_STATE ->
  (* [comment removed for export] *)
  AImplBlockC LB m implb (impl_one w i vb (stb + 32) vcap) ->
  (stb + SZ_SPCI_STATE <= implb \/ implb + SZ_SPCI_IMPL <= stb) ->
  (stb + SZ_SPCI_STATE <= vb \/ vb + 8 * vcap <= stb) ->
  (vb + 8 * vcap <= implb \/ implb + SZ_SPCI_IMPL <= vb) -> 8 * vcap <= 2^16 ->
  stk asegs m lo (bv_unsigned sp) -> lo + ASTATE_REMOVE_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned sp mod 16 = 0 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi -> accessible m stb SZ_SPCI_STATE ->
  evt asegs (state_remove_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB implb vb w i vcap lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (stb + 32)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_STATE_REMOVE) fc None m (seg_rom asegs)).

