Definition cr_W (lo : Z) (sp : word) (stb ff fp : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (stb + 104, stb + 144); (stb + 192, stb + 240); (stb + 248, stb + 252);
   (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16)]%Z.

Definition close_remote_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (LF : list fframe) (stb ioc implb lo shi : Z) (S : statev) (ds : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (ff fp : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (cr_W lo sp stb ff fp) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ AStateBlock LB m' stb ioc implb (st_closed S) ds
    /\ ACanaryReads m'
    /\ fresh_frame H LF 1 ff fp /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.

Definition close_remote_stmt : Prop :=
  forall (bs stb ioc implb lo shi : Z) (LB : list block) (LF : list fframe) (S : statev) (ds : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  ro_cells asegs m bs [C8 (wz (stb + 32))] -> bs mod 8 = 0 ->
  (* [comment removed for export] *)
  AStateBlock LB m stb ioc implb S ds -> st_lk S = 0 ->
  (st_fb S <> FB_empty -> fb_end (st_fb S) <= stb \/ stb + SZ_SPCI_STATE <= fb_begin (st_fb S)) ->
  ACanaryReads m ->
  stk asegs m lo (bv_unsigned sp) -> lo + ACLOSE_REMOTE_STACK <= bv_unsigned sp -> aceil <= lo ->
  (bs + 8 <= stb \/ stb + SZ_SPCI_STATE <= bs) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp + 64 <= shi ->
  aplace bs 8 -> (bs + 8 <= lo \/ bv_unsigned sp <= bs) -> fsobj H LF bs 8 -> accessible m bs 8 ->
  fsobj H LF stb SZ_SPCI_STATE ->
  (st_fb S <> FB_empty -> fsobj H LF (fb_begin (st_fb S)) (fb_cap (st_fb S))) ->
  evt asegs (close_remote_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB LF stb ioc implb lo shi S ds m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz bs) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_STREAM_CLOSE_REMOTE) fc None m (seg_rom asegs)).
End W4.

